{
  "application": "report-generation",
  "case_id": "case-global-cost-of-living-crisis-2026-en",
  "language": "en",
  "report": {
    "type": "analytics-report",
    "audience": "policy-analyst",
    "tone": "analytical, data-forward, professional"
  },
  "brief": {
    "title": "Global Cost of Living Crisis Index 2026: A Comparative Analysis of Economic Stress Across Cities and Regions",
    "one_liner": "An analytical report examining cost-of-living pressures, affordability gaps, and economic stress indicators across 80 major cities worldwide in 2026.",
    "goal": "Provide policy analysts and economic researchers with a clear understanding of which cities and regions face the most severe cost-of-living crises, what factors drive affordability challenges, and how income levels interact with living costs to create economic stress — enabling evidence-based prioritization of policy interventions."
  },
  "required_sections": [
    {
      "section_id": "executive-overview",
      "title": "Executive Overview",
      "objective": "Summarize the global cost-of-living landscape in 2026, highlighting the range of crisis tiers observed, the most and least affordable cities, and key headline statistics."
    },
    {
      "section_id": "regional-comparison",
      "title": "Regional Cost-of-Living Comparison",
      "objective": "Compare cost-of-living indices, rent indices, and purchasing power across regions (e.g., Western Europe, Asia, Americas) to identify regional patterns and outliers."
    },
    {
      "section_id": "affordability-analysis",
      "title": "Affordability and Rent Burden Analysis",
      "objective": "Analyze the rent-to-salary ratio across cities, identify cities where housing costs consume a disproportionate share of income, and examine the relationship between salary levels and rent costs."
    },
    {
      "section_id": "crisis-tier-profiling",
      "title": "Crisis Tier Profiling",
      "objective": "Profile each crisis tier and crisis label category, examining the average economic indicators within each group and identifying the characteristics that distinguish high-crisis cities from affluent ones."
    },
    {
      "section_id": "inflation-oil-exposure",
      "title": "Inflation and Oil Shock Exposure",
      "objective": "Assess how annual inflation rates and oil shock exposure levels correlate with cost-of-living indices and purchasing power, identifying cities most vulnerable to external economic shocks."
    },
    {
      "section_id": "key-findings-recommendations",
      "title": "Key Findings and Policy Implications",
      "objective": "Synthesize the analysis into actionable findings, highlight the cities and regions requiring urgent attention, and suggest areas for further research or policy focus."
    }
  ],
  "kpis": [
    {
      "name": "Median Cost of Living Index",
      "description": "The median cost_of_living_index across all 80 cities, providing a central benchmark for global living costs relative to New York."
    },
    {
      "name": "Average Rent-to-Salary Ratio",
      "description": "The mean rent_to_salary_ratio_pct across all cities, indicating the typical share of income consumed by rent globally."
    },
    {
      "name": "Purchasing Power Gap",
      "description": "The difference between the highest and lowest local_purchasing_power_index values, measuring the global inequality in purchasing power."
    },
    {
      "name": "High-Crisis City Count",
      "description": "The number of cities classified in the most severe cost_crisis_tier (highest tier number), indicating the breadth of acute economic stress."
    },
    {
      "name": "Average Annual Inflation Rate",
      "description": "The mean annual_inflation_rate_2025_pct across all cities, summarizing the global inflationary environment heading into 2026."
    }
  ],
  "analysis_dimensions": [
    "region",
    "crisis_label",
    "oil_shock_exposure",
    "cost_crisis_tier",
    "annual_inflation_rate_2025_pct"
  ]
}

