from html.parser import HTMLParser
import sys

class Validator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.tags = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag not in ('br','hr','img','input','meta','link','col','area','base','embed','source','track','wbr'):
            self.tags.append(tag)
    def handle_endtag(self, tag):
        if self.tags and self.tags[-1] == tag:
            self.tags.pop()
        elif tag in self.tags:
            while self.tags and self.tags[-1] != tag:
                self.errors.append(f'Unclosed tag: {self.tags.pop()}')
            if self.tags: self.tags.pop()
        else:
            self.errors.append(f'Unexpected closing tag: {tag}')

with open('/app/output/final_report.html') as f:
    content = f.read()

v = Validator()
v.feed(content)
if v.errors:
    print('HTML issues found:')
    for e in v.errors[:10]: print(f'  {e}')
else:
    print('HTML structure is valid.')

